export const habitatOf=id=>['shark','blue-whale','teal-whale','dolphin'].includes(id)?'sea':['seal','turtle','walrus','otter','penguin','crocodile','platypus'].includes(id)?'shore':'land';
export const SEA_ROUTE=[[925,470],[900,625],[610,709],[335,696],[55,600],[30,361],[150,155],[574,100],[890,210]];
export function seaPoint(phase){const v=((phase%1)+1)%1*SEA_ROUTE.length,i=Math.floor(v),a=SEA_ROUTE[i],b=SEA_ROUTE[(i+1)%SEA_ROUTE.length],p=v-i;return[a[0]+(b[0]-a[0])*p,a[1]+(b[1]-a[1])*p];}
export function createAnimalVisitors({project,findRoute,getState,redraw,announce,world,reduced=false,random=Math.random,onFish=()=>{}}){
 let animals=[],active=null,next=performance.now()+8000,index=0,last=0,paused=false,loadToken=0,marine=null,marineIndex=0,marineAt=0,fish=null,fishDue=0,throwing=null;
 const images=new Map(),base=new URL('./art/animals/',import.meta.url);
 async function imageFor(file){const url=new URL(file,base).href;if(images.has(url))return images.get(url);const i=new Image();i.src=url;await i.decode();images.set(url,i);return i;}
 const ready=fetch(new URL('catalog.json',base)).then(r=>{if(!r.ok)throw Error('catalog');return r.json();}).then(async m=>{animals=m.animals;index=Math.floor(random()*animals.length);await switchMarine(performance.now());}).catch(()=>{animals=[];});
 async function switchMarine(t){const entries=animals.filter(a=>habitatOf(a.id)!=='land');if(!entries.length)return;const preferred=['shark','seal','blue-whale','turtle','dolphin','teal-whale','walrus','otter','penguin','crocodile','platypus'];const id=preferred[marineIndex++%preferred.length],e=entries.find(x=>x.id===id)||entries[0];const image=await imageFor(e.sheet);marine={...e,image,start:t,phase:0,x:880,y:470,onLand:false};marineAt=t+55000;fishDue=t+9000;redraw();}
 const canvasMark=(kind,size=80)=>`<foreignObject x="${-size/2}" y="${-size+9}" width="${size}" height="${size}" pointer-events="none"><canvas xmlns="http://www.w3.org/1999/xhtml" data-animal-canvas="${kind}" width="128" height="128" style="display:block;width:${size}px;height:${size}px;image-rendering:pixelated"></canvas></foreignObject>`;
 function render(){if(!active)return null;const cellPoint=project(...active.cell),seg=active.segment,progress=seg?Math.min(1,seg.elapsed/1100):0,[x,y]=seg?[seg.from[0]+(seg.to[0]-seg.from[0])*progress,seg.from[1]+(seg.to[1]-seg.from[1])*progress]:cellPoint;return{depth:active.cell[0]+active.cell[1]+.12,html:`<g id="animal-visitor" transform="translate(${x} ${y})"><title>${active.name} 친구</title><ellipse cy="1" rx="17" ry="5" fill="#63794b20"/>${canvasMark('land')}<ellipse data-visitor="1" cx="0" cy="-27" rx="27" ry="31" fill="transparent" role="button" tabindex="0" aria-label="${active.name} 친구에게 인사하기"/></g>`};}
 function seaMarkup(){return `<g id="sea-life">${marine?`<g id="marine" transform="translate(${marine.x} ${marine.y})">${canvasMark('sea',habitatOf(marine.id)==='sea'?118:85)}<ellipse data-marine="1" cy="-10" rx="43" ry="35" fill="transparent" role="button" tabindex="0" aria-label="${marine.name} 헤엄치는 친구"/></g>`:''}<g id="flying-fish"></g><g id="shore-fish" ${fish?'':'display="none"'} transform="translate(754 534)"><ellipse rx="18" ry="6" fill="#5b694729"/><g data-fish="1" role="button" tabindex="0" aria-label="바다 친구가 준 물고기 줍기"><path d="M-14-6Q0-22 15-8Q0 8-14-6L-26-17V2Z" fill="#a5cbd1" stroke="#677f85" stroke-width="2"/><circle cx="8" cy="-9" r="2" fill="#526064"/><rect x="-30" y="-27" width="60" height="40" fill="transparent"/></g></g></g>`;}
 function paint(kind,image,frame,row,{water=false,waterLevel=water?1:0}={}){const canvas=world.querySelector(`[data-animal-canvas="${kind}"]`);if(!canvas?.getContext||!image)return;const c=canvas.getContext('2d');c.clearRect(0,0,128,128);c.imageSmoothingEnabled=false;c.save();if(waterLevel>0){c.beginPath();c.rect(0,0,128,128-39*waterLevel);c.clip();}c.drawImage(image,frame*128,row*128,128,128,0,16*waterLevel,128,128);c.restore();if(waterLevel>0){c.globalAlpha=waterLevel;c.strokeStyle='#e1f4d9';c.lineWidth=2;c.beginPath();c.ellipse(64,91,40,7,0,0,Math.PI*2);c.stroke();c.strokeStyle='#8fc4bd';c.beginPath();c.ellipse(64,95,47,9,0,0,Math.PI);c.stroke();c.globalAlpha=1;}}
 async function spawn(t){if(!animals.length||active)return;const token=++loadToken,land=animals.filter(e=>habitatOf(e.id)==='land'),entry=land[index++%land.length];if(!entry)return;
 try{const image=await imageFor(entry.sheet),specialImage=entry.special?await imageFor(entry.special):null;if(token!==loadToken)return;let path=[];for(const start of [[1,5],[6,1],[7,5],[5,7]]){for(const goal of [[5,6],[6,5],[2,6],[6,2]]){path=findRoute(getState(),start,goal);if(path.length>1)break;}if(path.length>1)break;}if(path.length<2){next=t+20000;return;}
 active={...entry,image,specialImage,cell:[...path[0]],path,step:0,row:0,walk:false,phase:0,segment:null,waitUntil:0,leaving:false,origin:[...path[0]]};redraw();announce(entry.name+' 친구가 잠깐 놀러 왔어요.');}catch{next=t+20000;}}
 function tick(t,blocked=false){const dt=Math.min(.1,Math.max(0,(t-last)/1000));last=t;if(blocked||document.hidden){if(active?.waitUntil)active.waitUntil+=dt*1000;if(marine)marine.start+=dt*1000;marineAt+=dt*1000;fishDue+=dt*1000;next+=dt*1000;paused=true;return;}
 if(paused){paused=false;if(active?.segment)active.segment.start=t-active.segment.elapsed;}
 if(marine){const m=marine,elapsed=(t-m.start)/1000;let [x,y]=seaPoint(elapsed/44),onLand=false,waterLevel=1;
 if(habitatOf(m.id)==='shore'){// Enter/leave at the eastern beach, then rest beside the shore.
 const cycle=elapsed%38;if(cycle>=14&&cycle<32){const q=Math.min(1,cycle<21?(cycle-14)/7:cycle<26?1:(32-cycle)/6);x=925+(790-925)*q;y=470;onLand=q>.45;waterLevel=1-q;}else{const f=cycle<14?cycle/14:(cycle-32)/6;x=925+Math.sin(f*Math.PI)*12;y=470+Math.sin(f*Math.PI*2)*55;}}
 m.x=x;m.y=y;m.onLand=onLand;m.phase=elapsed;world.querySelector('#marine')?.setAttribute('transform',`translate(${x.toFixed(2)} ${(y+(!onLand?Math.sin(elapsed*2)*2:0)).toFixed(2)})`);paint('sea',m.image,onLand?1+Math.floor(elapsed*7)%5:0,onLand?2:0,{water:!onLand,waterLevel});
 if(t>=fishDue&&!fish&&!throwing&&habitatOf(m.id)==='sea'){throwing={start:t,from:[x,y]};fishDue=t+40000;announce(m.name+' 친구가 물고기를 선물했어요! 해변을 눌러 주워 보세요.');}
 if(t>=marineAt){marineAt=t+60000;switchMarine(t);}}
 if(throwing){const p=Math.min(1,(t-throwing.start)/1500),[x,y]=throwing.from,fx=x+(754-x)*p,fy=y+(534-y)*p-Math.sin(p*Math.PI)*140;const el=world.querySelector('#flying-fish');if(el){el.innerHTML='<path d="M-10 0Q0-12 12 0Q0 12-10 0L-18-7V7Z" fill="#c2dce0" stroke="#6a9299" stroke-width="2"/>';el.setAttribute('transform',`translate(${fx} ${fy}) rotate(${p*360})`);}if(p===1){throwing=null;fish=true;if(el)el.innerHTML='';world.querySelector('#shore-fish')?.removeAttribute('display');}}
 if(!active){if(t>=next){next=t+30000;spawn(t);}return;}
 const a=active;a.phase+=dt;const special=!!a.specialImage&&(!a.walk||t<(a.greetingUntil||0));paint('land',special?a.specialImage:a.image,special?(t<(a.greetingUntil||0)?4:a.phase%12>6?3:0):a.walk?1+Math.floor(a.phase*8)%5:0,special?0:a.row);
 if(a.waitUntil){if(t<a.waitUntil)return;a.waitUntil=0;a.path=findRoute(getState(),a.cell,a.origin);a.step=0;a.leaving=true;if(a.path.length<2){active=null;next=t+25000;redraw();return;}}
 if(!a.segment){const dest=a.path[a.step+1];if(!dest){if(a.leaving){active=null;next=t+25000;}else{a.walk=false;a.waitUntil=t+12000;}redraw();return;}const route=findRoute(getState(),a.cell,dest);if(route.length!==2){active=null;next=t+18000;redraw();return;}const from=project(...a.cell),to=project(...dest),dx=to[0]-from[0],dy=to[1]-from[1];a.row=Math.abs(dx)>=Math.abs(dy)?dx<0?2:3:dy<0?1:0;a.walk=!reduced;a.segment={from,to,start:t,elapsed:0};}
 const s=a.segment;s.elapsed=t-s.start;const p=Math.min(1,s.elapsed/1100),x=s.from[0]+(s.to[0]-s.from[0])*p,y=s.from[1]+(s.to[1]-s.from[1])*p;world.querySelector('#animal-visitor')?.setAttribute('transform',`translate(${x.toFixed(2)} ${y.toFixed(2)})`);if(p===1){a.cell=[...a.path[++a.step]];a.segment=null;}}
 function greet(){if(!active)return;active.greetingUntil=performance.now()+2000;announce(active.name+' 친구에게 반갑게 인사했어요.');}
 function collectFish(){if(!fish)return false;fish=false;world.querySelector('#shore-fish')?.setAttribute('display','none');onFish();announce('바다 친구의 물고기를 주웠어요. 섬 수첩에 보관했어요.');return true;}
 return{ready,render,seaMarkup,tick,greet,collectFish,get active(){return active;},get marine(){return marine;},get hasFish(){return !!fish;}};
}
